<p class="wa-intro">Kirim informasi BKK melalui WhatsApp pribadi Anda.</p><ol class="wa-steps" aria-label="Cara menggunakan"><li><span>1</span> Pilih penerima</li><li><span>2</span> Tulis pesan</li><li><span>3</span> Buka WhatsApp &amp; kirim</li></ol>
<form method="get" class="filter-form card wa-filters"><label><span><?= panel_icon('pengguna') ?> Kirim kepada</span><select name="group" id="wa-group"><?php foreach(['pelamar'=>'Pelamar','tracer'=>'Alumni mencari kerja','semua'=>'Pelamar dan alumni mencari kerja'] as $value=>$label):?><option value="<?= $value ?>" <?= $filters['group']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label id="wa-job-field" <?= $filters['group']==='tracer'?'hidden':'' ?>><span><?= panel_icon('lowongan') ?> Lowongan</span><select name="lowongan" id="wa-job" <?= $filters['group']==='tracer'?'disabled':'' ?>><option value="">Semua lowongan</option><?php foreach($jobs as $job):?><option value="<?= (int)$job['lowongan_id'] ?>" <?= $filters['lowongan']===(int)$job['lowongan_id']?'selected':'' ?>><?= e($job['posisi'].' - '.$job['perusahaan']) ?></option><?php endforeach;?></select></label><label id="wa-year-field" <?= $filters['group']==='pelamar'?'hidden':'' ?>><span><?= panel_icon('calendar') ?> Tahun lulus alumni</span><select id="wa-year" name="tahun_lulus" <?= $filters['group']==='pelamar'?'disabled':'' ?>><option value="">Semua angkatan</option><?php foreach($years as $year):?><option value="<?= (int)$year ?>" <?= $filters['tahun_lulus']===(int)$year?'selected':'' ?>><?= (int)$year ?></option><?php endforeach;?></select></label><label><span><?= panel_icon('akun') ?> Cari nama / nomor</span><input type="search" name="q" value="<?= e($filters['q']) ?>" maxlength="100"></label><button type="submit">Cari penerima</button><a class="filter-reset" href="<?= e(base_url('panel/whatsapp/?'.http_build_query(['group'=>$filters['group']]))) ?>">Reset</a></form>
<div class="wa-result"><strong><?= $total ?> orang ditemukan</strong><span>Cari nama, nomor, atau email. Pilihan Anda tetap tersimpan saat berganti halaman.</span></div>
<?php if(!$total): ?><p class="notice">Tidak ada hasil pada pencarian ini. Coba kata lain atau kelompok lain. Penerima yang sudah Anda pilih tetap tersimpan.</p><?php endif; ?>
<form method="post" action="<?= e(base_url('panel/whatsapp/buat.php')) ?>" class="wa-compose" data-selection-url="<?= e(base_url('panel/whatsapp/pilihan.php')) ?>">
<?= csrf_field() ?><input type="hidden" name="submission_key" value="<?= e($_SESSION['wa_create_key']) ?>"><?php foreach($filters as $key=>$value):?><input type="hidden" name="<?= $key ?>" value="<?= e((string)$value) ?>"><?php endforeach;?>
<input type="hidden" name="mode" value="basket"><input type="hidden" name="page" value="<?= $page ?>"><section class="card"><h2><?= panel_icon('pengguna') ?> 1. Pilih penerima</h2><div class="wa-selection-toolbar"><strong><span id="wa-basket-count"><?= $selectedCount ?></span> orang terpilih</strong><div><button type="submit" name="action" value="add_all" formaction="<?= e(base_url('panel/whatsapp/pilihan.php')) ?>" formnovalidate class="button secondary" data-selection-action="add_all" <?= !$availableCount?'disabled':'' ?>>Pilih semua <?= $availableCount ?> hasil</button><button type="submit" name="action" value="clear" formaction="<?= e(base_url('panel/whatsapp/pilihan.php')) ?>" formnovalidate class="button secondary" data-selection-action="clear">Kosongkan pilihan</button></div><p id="wa-selection-status" role="status">Centang beberapa orang, lalu cari nama lain atau pindah halaman. Pilihan akan tetap tersimpan.</p></div>
<div class="table-scroll" tabindex="0" aria-label="Daftar calon penerima"><table><thead><tr><th>Pilih</th><th>Nama</th><th>WhatsApp</th><th>Sumber</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><input type="hidden" name="visible[]" value="<?= e($row['key']) ?>"><input data-phone="<?= e($row['nomor']) ?>" <?= isset($selectedPhones[$row['nomor']])?'checked':'' ?> <?= !$row['selectable']?'disabled':'' ?> type="checkbox" name="selected[]" value="<?= e($row['key']) ?>" aria-label="<?= e('Pilih '.$row['nama']) ?>"></td><td><?= e($row['nama']) ?></td><td><?= e($row['nomor']) ?></td><td><?= e($row['sumber']) ?><small><?= !$row['selectable']?'Meminta berhenti':($row['consent']?'Persetujuan tercatat':'Persetujuan belum tercatat') ?></small></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">Tidak ada hasil. Pilihan dari pencarian lain tetap tersimpan.</td></tr><?php endif;?></tbody></table></div>
<?php if($pages>1):?><nav class="pagination" aria-label="Halaman penerima"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;}?><a href="<?= e(base_url('panel/whatsapp/?'.http_build_query($filters+['page'=>$target]))) ?>"><?= $label ?></a><?php endforeach;?></nav><p class="muted">Halaman <?= $page ?>/<?= $pages ?>. Centang penerima di beberapa halaman; jumlah terpilih tetap digabung.</p><?php endif;?></section>
<section class="card editor-form"><h2><?= panel_icon('message') ?> 2. Tulis pesan</h2><label for="wa-title">Nama pesan<input id="wa-title" name="judul" maxlength="150" value="<?= e($draft['judul']) ?>" required></label><label for="wa-message">Pesan<textarea id="wa-message" name="pesan" rows="4" maxlength="1500" required><?= e($draft['pesan']) ?></textarea></label><small>Tulis {nama} untuk mengisi nama penerima secara otomatis.</small><details class="wa-extra" <?= $draft['tautan']!==''?'open':'' ?>><summary>Tambahkan tautan lowongan / poster</summary><label for="wa-link">Tautan informasi / poster (opsional)<input id="wa-link" name="tautan" type="url" maxlength="2048" placeholder="https://..." value="<?= e($draft['tautan']) ?>"></label><small>Gunakan tautan publik yang dapat diakses penerima. Berkas lampiran ditambahkan manual di WhatsApp.</small></details><div class="wa-live-preview"><strong>Contoh pesan untuk <?= e($selectedContacts[0]['nama']??$rows[0]['nama']??'Nama penerima') ?></strong><p id="wa-preview" data-name="<?= e($selectedContacts[0]['nama']??$rows[0]['nama']??'Nama penerima') ?>"><?= e(wa_message($draft['pesan'],$selectedContacts[0]['nama']??$rows[0]['nama']??'Nama penerima',$draft['tautan'])) ?></p></div><p class="wa-send-note">Langkah berikutnya menampilkan daftar tombol WhatsApp. Pesan belum dikirim.</p><button id="wa-continue" type="submit" <?= !$selectedCount?'disabled':'' ?>><?= panel_icon('whatsapp') ?> Lanjut ke WhatsApp (<span id="wa-selected-count"><?= $selectedCount ?></span>)</button></section></form>
<details class="wa-history"><summary>Riwayat pesan (<?= $historyTotal ?>)</summary><div class="table-scroll"><table><thead><tr><th>Judul / dibuat (WIB)</th><th>Penerima</th><th>Dibuka</th><th>Ditandai dikirim</th><th></th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?= e($item['judul']) ?><small><?= e($item['created_at']) ?></small></td><td><?= (int)$item['total'] ?></td><td><?= (int)$item['opened'] ?></td><td><?= (int)$item['marked'] ?></td><td><a href="<?= e(base_url('panel/whatsapp/detail.php?id='.$item['id'])) ?>">Buka daftar</a></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="5">Belum ada daftar pesan.</td></tr><?php endif;?></tbody></table></div>
<?php if($historyPages>1):?><nav class="pagination" aria-label="Halaman riwayat"><?php foreach(['Sebelumnya'=>$historyPage-1,'Berikutnya'=>$historyPage+1] as $label=>$target):if($target<1||$target>$historyPages){continue;}?><a href="<?= e(base_url('panel/whatsapp/?'.http_build_query($filters+['history_page'=>$target]))) ?>"><?= $label ?></a><?php endforeach;?></nav><?php endif;?></details></div>
